{"code": "export async function main(input: Record<string, never>) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const qualifying = issues.filter((i) => i.count >= 100);
  const out = [];
  for (const issue of qualifying) {
    const { events } = await sdk.sentry.listIssueEvents({ issueId: issue.id });
    out.push({ issue, events });
  }
  return out;
}"}

{"code": "export async function main(input: Record<string, never>) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const qualifying = issues.filter((i) => i.project === "jobs" && i.count >= 100);

  const rows: { shortId: string; count: number; status: string; latestRelease: string | null }[] = [];
  for (const issue of qualifying) {
    const { events } = await sdk.sentry.listIssueEvents({ issueId: issue.id });
    const sorted = [...events].sort(
      (a, b) => Date.parse(b.timestamp) - Date.parse(a.timestamp)
    );
    const newest = sorted[0];
    const release =
      newest && typeof newest.release === "string" && newest.release.trim() !== ""
        ? newest.release
        : null;
    rows.push({
      shortId: issue.shortId,
      count: issue.count,
      status: issue.status,
      latestRelease: release,
    });
  }

  rows.sort((a, b) => b.count - a.count);
  return rows;
}"}
